    'c.cv.b': 'اینجا سی‌وی کوتاه است: ۱ یا ۲ صفحه. معلومات تماس، تجربهٔ کاری، تحصیلات، زبان‌ها و مهارت‌های خود را بنویسید. عکس لازم نیست. لازم نیست دین، سن یا حالت مدنی (متأهل یا مجرد) خود را بنویسید. دربارهٔ کارهایی که کرده می‌توانید راست بگویید. از کسی بخواهید که هالندی شما را کنترول کند.', // nieuw, nalezen
