    'c.shelves.b': 'وقتی رف‌ها را پر می‌کنید، به تاریخ روی جنس‌ها نگاه کنید. جنس‌هایی را که تاریخ شان نزدیک‌تر است در پیش‌رو بگذارید، و جنس‌های نو را در عقب. مشتری‌ها از پیش‌رو برمی‌دارند، پس جنس‌های کهنه زودتر فروخته می‌شوند. آیا تاریخ یک جنس گذشته، یا خراب شده است؟ آن را از رف بردارید و بپرسید که با آن چه کنید. راهروها را از قطی‌ها و کراچی‌ها خالی نگه دارید. مقررات در هر کمپنی فرق می‌کند: از سرپرست خود بپرسید که مقررات جای کار شما چیست.',
    'c.shelves.p': 'با جنس‌هایی که تاریخ شان گذشته چه کنم؟',
    'c.shelves.s': 'شما شیر نو را در رف می‌گذارید. در پیش‌روی رف شیری است که تاریخش نزدیک‌تر است. چه می‌کنید؟', // nieuw, nalezen (AI-correctie 2 nov 2026)
    'c.shelves.o1': 'شیر نو را در عقب بگذارید، و شیر کهنه را در پیش‌رو.',
    'c.shelves.o2': 'شیر نو را در پیش‌رو بگذارید، چون تازه‌تر است.',
    'c.shelves.o3': 'شیر کهنه را دور بیندازید.', // nieuw, nalezen (AI-correctie 2 nov 2026)
    'c.shelves.w': 'مشتری‌ها از پیش‌رو برمی‌دارند. وقتی جنس‌های کهنه اول فروخته شوند، خوراک کمتر دور انداخته می‌شود.',
    'c.checkout': 'کارت هویت برای الکول و تنباکو',
    'c.checkout.b': 'شما اجازه ندارید به کسی که کمتر از ۱۸ سال عمر دارد الکول یا تنباکو بفروشید: این قانون است. مطمئن نیستید که مشتری چند ساله است؟ کارت هویتش را بخواهید. بسیاری از دکان‌ها از هر کسی که جوان‌تر از ۲۵ سال معلوم می‌شود کارت هویت می‌خواهند. کارت هویت ندارد، یا کمتر از ۱۸ سال است؟ پس به او نفروشید، و با ادب باشید. مقررات در هر کمپنی فرق می‌کند: از سرپرست خود بپرسید که مقررات جای کار شما چیست.',
    'c.checkout.p': 'بدون کارت هویت اجازه ندارم این را بفروشم.',
    'c.checkout.s': 'یک مرد جوان می‌خواهد بیر بخرد. به نظر حدود ۱۷ ساله است. می‌گوید ۱۹ ساله است، اما کارت هویت با خود ندارد. چه می‌کنید؟',
    'c.checkout.o1': 'بگویید که بدون کارت هویت فروخته نمی‌توانید.', // nagelezen (2e lezing)
    'c.checkout.o2': 'به او بفروشید، چون می‌گوید ۱۹ ساله است.',
    'c.checkout.o3': 'به او بفروشید، اما فقط یک قطی.',
    'c.checkout.w': 'بدون کارت هویت نمی‌توانید عمر او را بدانید. فروختن الکول به کسی که کمتر از ۱۸ سال دارد خلاف قانون است، و دکان ممکن است جریمه شود.',
    'c.counting': 'Vijfentwintig: اول ۵، بعد ۲۰', // nieuw, nalezen
    'c.counting.b': 'در هالندی، عددهای ۰ تا ۱۲ هر کدام کلمهٔ خود را دارند: nul، een، twee، drie، vier، vijf، zes، zeven، acht، negen، tien، elf، twaalf. عددهای ۱۳ تا ۱۹ با -tien ختم می‌شوند: dertien، veertien، vijftien، zestien، zeventien، achttien، negentien. ده‌ها با -tig ختم می‌شوند: twintig، dertig، veertig، vijftig، zestig، zeventig، tachtig، negentig. از ۲۱ تا ۹۹ اول رقم آخر گفته می‌شود: ۲۵ می‌شود vijfentwintig، یعنی «پنج و بیست». پس ۴۷ می‌شود zevenenveertig و ۷۴ می‌شود vierenzeventig. Dertien و dertig تقریباً یکسان شنیده می‌شوند: به آخر آن گوش کنید. مطمئن نیستید؟ رقم‌ها را یکی‌یکی تکرار کنید.', // nieuw, nalezen
    'c.counting.p': 'چهار، هفت؟ یعنی چهل و هفت؟', // nieuw, nalezen
    'c.counting.s': 'سرپرست تان می‌گوید: «Ga naar gang zevenenveertig.» کدام راهرو است؟', // nieuw, nalezen
    'c.counting.o1': 'راهروی ۴۷.', // nieuw, nalezen
    'c.counting.o2': 'راهروی ۷۴.', // nieuw, nalezen
    'c.counting.o3': 'راهروی ۴۰.', // nieuw, nalezen
    'c.counting.w': '«Zevenenveertig» یعنی «هفت و چهل»: اول ۷، بعد ۴۰. پس راهروی ۴۷ است. بسیاری از تازه‌واردها ۷۴ می‌شنوند و به راهروی غلط می‌روند.', // nieuw, nalezen
    'c.hours': '«Half acht» یعنی ۷:۳۰',
    'c.hours.b': 'در هالندی، «half» تا ساعت بعدی حساب می‌شود: half acht یعنی ۷:۳۰، نه ۸:۳۰. Kwart over acht یعنی ۸:۱۵، و kwart voor acht یعنی ۷:۴۵. ساعت‌های کار خود را خود تان حساب کنید: وقت ختم منهای وقت شروع، منهای وقت تفریح. برای وقت تفریح اکثراً پول داده نمی‌شود. ساعت‌های کار خود را هر روز یادداشت کنید.',
    'c.hours.p': '«Half acht»؟ یعنی نیم ساعت پیش از هشت؟',
    'c.hours.s': 'سرپرست تان می‌گوید: «Morgen begin je om half negen.» فردا ساعت چند شروع می‌کنید؟',
    'c.hours.o1': 'ساعت ۸:۳۰.',
    'c.hours.o2': 'ساعت ۹:۳۰.',
    'c.hours.o3': 'ساعت ۸:۰۰.',
    'c.hours.w': '«Half negen» یعنی نیم ساعت پیش از نه: ۸:۳۰. بسیاری از تازه‌واردان فکر می‌کنند که ۹:۳۰ است، و یک ساعت ناوقت می‌آیند.',
    'c.measures': 'هوشیارانه بشمارید، اندازه کنید، حدس نزنید',
    'c.measures.b': 'قطی‌های زیاد را باید بشمارید؟ قطی‌های یک طبقه را بشمارید، و تعداد طبقه‌ها را. بعد ضرب کنید: ۸ قطی در یک طبقه و ۵ طبقه می‌شود ۴۰ قطی. برای مواد پاک‌کاری، همان مقداری را که روی لیبل نوشته شده اندازه کنید. زیادتر بهتر نیست: به پوست شما ضرر رسانده می‌تواند و پول ضایع می‌شود. از یک عدد مطمئن نیستید؟ دوباره بشمارید، یا بپرسید. مقررات در هر کمپنی فرق می‌کند: از سرپرست خود بپرسید که مقررات جای کار شما چیست.',
    'c.measures.p': 'آن را دو بار شمردم.',
    'c.measures.s': 'یک پالت ۶ طبقه دارد. هر طبقه ۸ قطی دارد. سرپرست تان می‌پرسد که چند قطی است. چه می‌گویید؟',
