    'c.aihelp': 'هوش مصنوعی کمک می‌کند، یک انسان کنترول می‌کند',
    'c.aihelp.b': 'اپ‌های هوش مصنوعی و چت‌بات‌ها، مانند ChatGPT، می‌توانند ترجمه کنند، یک نامه را توضیح بدهند یا در نوشتن پیام به شما کمک کنند. این مفید است. اما هوش مصنوعی گاهی اشتباه می‌کند و باز هم خیلی مطمئن معلوم می‌شود. موضوع دربارهٔ قرارداد، معاش، دوا یا مصئونیت است؟ پس همیشه جواب را با یک انسان کنترول کنید. مثلاً با سرپرست خود، بخش منابع بشری (HR) یا Juridisch Loket.',
    'c.aihelp.p': 'این درست است؟ یک نظر همراه من انداخته می‌توانید؟',
    'c.aihelp.s': 'از یک چت‌بات دربارهٔ قرارداد خود می‌پرسید. می‌گوید که شما پول رخصتی (vakantiegeld) نمی‌گیرید. چه می‌کنید؟',
    'c.aihelp.o1': 'از HR یا Juridisch Loket بخواهید که آن را کنترول کنند.', // nagelezen (2e lezing)
    'c.aihelp.o2': 'باور کنید: چت‌بات خیلی مطمئن معلوم می‌شود.',
    'c.aihelp.o3': 'چیزی نگویید و آن را فراموش کنید.',
    'c.aihelp.w': 'چت‌بات می‌تواند دربارهٔ مقررات و قراردادها اشتباه کند. در هالند تقریباً هر کارگر پول رخصتی می‌گیرد. کسی که مقررات را می‌داند آن را کنترول کرده می‌تواند.',
    'c.aiprivate': 'پیش از تایپ کردن فکر کنید',
    'c.aiprivate.b': 'هر چیزی که در یک چت‌بات تایپ می‌کنید ممکن است ذخیره شود و کمپنی سازندهٔ آن از آن استفاده کند. پس هرگز نمبر BSN، رمز یا معلومات بانکی خود را تایپ نکنید. نام یا عکس مشتری‌ها، مریض‌ها یا همکاران، یا کاغذهای کاری را هم داخل نکنید. بسیاری از کارفرمایان برای هوش مصنوعی مقررات دارند. اول بپرسید که اجازه دارید برای کار خود از آن استفاده کنید یا نی. مقررات در هر کمپنی فرق می‌کند: از سرپرست خود بپرسید که مقررات جای کار شما چیست.',
    'c.aiprivate.p': 'اجازه دارم برای این کار از هوش مصنوعی استفاده کنم؟',
    'c.aiprivate.s': 'می‌خواهید یک چت‌بات دربارهٔ یک مشتری گزارش بنویسد. در گزارش نام و آدرس مشتری است. چه می‌کنید؟',
    'c.aiprivate.o1': 'اول بپرسید، و نام و آدرس را بیرون کنید.', // nagelezen (2e lezing)
    'c.aiprivate.o2': 'همه چیز را در چت‌بات بگذارید: زودتر است.',
    'c.aiprivate.o3': 'گزارش را به یک دوست بفرستید تا آن را کنترول کند.',
    'c.aiprivate.w': 'نام‌ها و آدرس‌ها معلومات شخصی هستند. نباید همین‌طور به یک کمپنی دیگر بروند. کارفرمای شما می‌داند کدام اپ‌ها اجازه است.',
    'c.aifake': 'صداها و ویدیوهای جعلی',
    'c.aifake.b': 'با هوش مصنوعی، جنایتکاران می‌توانند صدای کسی را کاپی کنند و عکس و ویدیوی جعلی بسازند. تماس یا پیامی که مانند رئیس، بانک یا یکی از فامیل شما معلوم می‌شود، ممکن است جعلی باشد. وقتی عجله، پول و یک شمارهٔ نو در کار است، احتیاط کنید. تیلفون را قطع کنید و خود تان به شماره‌ای که می‌شناسید زنگ بزنید. یک بانک، کارفرما یا پولیس واقعی هیچ‌گاه کودهای شما را نمی‌خواهد.',
    'c.aifake.p': 'تیلفون را قطع می‌کنم و خودم دوباره زنگ می‌زنم.',
    'c.aifake.s': 'تیلفون تان زنگ می‌زند. صدایی که درست مانند صدای رئیس تان است می‌گوید: «این بل را همین حالا بپردازید، عاجل است.» چه می‌کنید؟',
    'c.aifake.o1': 'تیلفون را قطع کنید و خود تان به رئیس زنگ بزنید.', // nagelezen (2e lezing)
    'c.aifake.o2': 'زود بپردازید: رئیس تان است.',
    'c.aifake.o3': 'کود بانکی خود را بدهید تا رئیس بتواند بپردازد.',
    'c.aifake.w': 'صدا را می‌شود با هوش مصنوعی کاپی کرد. عجله و پول با هم یک نشانهٔ خطر است. زنگ زدن به شماره‌ای که می‌شناسید یک کنترول زود و مصئون است.',
    'c.aiplan': 'کی این را تصمیم گرفت؟',
    'c.aiplan.b': 'کمپنی‌های بیشتر و بیشتر می‌گذارند که یک اپ یا کمپیوتر دربارهٔ چیزها تصمیم بگیرد. مثلاً تقسیم اوقات کار را می‌سازد یا سرعت شما را با سکنر اندازه می‌کند. شما می‌توانید بپرسید که چه معلوماتی دربارهٔ شما جمع می‌شود. تصمیم مهمی دربارهٔ شما گرفته شده، مانند ساعت‌های کمتر، یک اخطار یا اخراج؟ بپرسید که کی آن را تصمیم گرفت. یک کمپیوتر آن تصمیم را به تنهایی گرفته؟ پس می‌توانید بخواهید که یک انسان دوباره آن را کنترول کند و توضیح بدهد. ساعت‌های کار خود را یادداشت کنید. معلومات عمومی. برای وضعیت خود تان: از کارفرما، اتحادیهٔ کارگری یا Juridisch Loket بپرسید.',
    'c.aiplan.p': 'یک انسان به این یک نظر انداخته می‌تواند؟',
    'c.aiplan.s': 'اپ تقسیم اوقات ماه آینده به شما ساعت‌های خیلی کمتر می‌دهد. هیچ کس نمی‌گوید چرا. چه می‌کنید؟',
    'c.aiplan.o1': 'بخواهید که یک انسان آن را توضیح بدهد.', // nagelezen (2e lezing)
    'c.aiplan.o2': 'قبول کنید: اپ همیشه درست می‌گوید.',
    'c.aiplan.o3': 'از چت‌بات داخل اپ بپرسید چرا.', // nagelezen (2e lezing)
