    'c.harvest': "سرعت کار و مزد فی دانه", // nagelezen (2e lezing)
    'c.harvest.b': "در گلخانه اکثراً با یک سرعت ثابت (tempo) کار می‌کنید. بعضی کارفرمایان فی جعبه، فی قطار یا فی کیلو پول می‌دهند: این مزد فی دانه (stukloon) است. حتی با مزد فی دانه باید برای هر ساعتی که کار می‌کنید دست کم حد اقل معاش را بگیرید. مقدار آن را در rijksoverheid.nl ببینید. هر روز ساعت‌ها و جعبه‌های خود را یادداشت کنید و با ورق معاش خود مقایسه کنید. تیز کار کردن خوب است، اما مصئون کار کردن مهم‌تر است. معلومات عمومی. برای وضعیت خود تان: از اتحادیهٔ کارگری، Juridisch Loket یا FairWork بپرسید.", // nagelezen (2e lezing)
    'c.harvest.p': "امروز چند جعبه را تمام کردم؟", // nagelezen (2e lezing)
    'c.harvest.s': "برای هر جعبه به شما پول می‌دهند. این هفته فی ساعت کمتر از حد اقل معاش پول می‌گیرید. چه می‌کنید؟", // nieuw, nalezen (AI-correctie 2 nov 2026)
    'c.harvest.o1': "فهرست ساعت‌ها و جعبه‌های خود را نشان بدهید.", // nieuw, nalezen (AI-correctie 2 nov 2026)
    'c.harvest.o2': "چیزی نگویید و تیزتر کار کنید.", // nieuw, nalezen (AI-correctie 2 nov 2026)
    'c.harvest.o3': "قبول کنید: با مزد فی دانه این عادی است.", // nieuw, nalezen (AI-correctie 2 nov 2026)
    'c.harvest.w': "با مزد فی دانه هم باید برای هر ساعتی که کار کرده‌اید دست کم حد اقل معاش را بگیرید. فهرست ساعت‌ها و جعبه‌های خود شما کمک می‌کند نشان بدهید چه کار کرده‌اید. اگر درست نشد، کمک بخواهید.", // nagelezen (2e lezing)
    'c.greensafe': "گرمی و دواهای زراعتی", // nagelezen (2e lezing)
    'c.greensafe.b': "در گلخانه هوا می‌تواند خیلی گرم شود، حتی در بهار. زیاد آب بنوشید، حتی پیش از اینکه تشنه شوید، و تفریح خود را در یک جای سرد بگیرید. سرچرخی دارید، دل‌بدی دارید یا سر تان درد می‌کند؟ کار را بس کنید و به کسی بگویید. نباتات گاهی با مواد کیمیایی دواپاشی می‌شوند (spuitmiddelen). روی دروازهٔ گلخانه‌ای که تازه دواپاشی شده اکثراً یک لوحه است. تا وقتی سرپرست شما نگفته که دوباره مصئون است، داخل نروید. معلومات عمومی. برای وضعیت خود تان: از کارفرما، اتحادیهٔ کارگری یا Juridisch Loket بپرسید.", // nagelezen (2e lezing)
    'c.greensafe.p': "آیا حالا می‌توانم در این گلخانه کار کنم؟", // nagelezen (2e lezing)
    'c.greensafe.s': "امروز صبح یک گلخانه دواپاشی شده. روی دروازه یک لوحه است. یک همکار می‌گوید: «بیایید، فقط یک لحظه است.» چه می‌کنید؟", // nagelezen (2e lezing) // nagelezen AI ronde 3
    'c.greensafe.o1': "بیرون بمانید و بپرسید که چه وقت مصئون است.", // nagelezen (2e lezing)
    'c.greensafe.o2': "زود داخل بروید و نفس خود را نگه دارید.", // nagelezen (2e lezing)
    'c.greensafe.o3': "داخل بروید و بعد دست‌های خود را خوب بشویید.", // nagelezen (2e lezing)
    'c.greensafe.w': "دواهای زراعتی می‌توانند به پوست، چشم‌ها و شش‌های شما ضرر برسانند، حتی وقتی هیچ بویی حس نمی‌کنید. بعد از دواپاشی یک وقت انتظار است تا دوباره بشود داخل رفت. سرپرست شما می‌داند که چه وقت تمام می‌شود.", // nagelezen (2e lezing)
