    'c.details.b': "در شروع کار، معلومات خود را می‌دهید. یعنی نام، آدرس، نمبر تیلفون، تاریخ تولد و BSN. نام خود را آهسته و حرف به حرف هجی کنید. بعد نام خود را در قرارداد و ورق معاش کنترول کنید. یک اشتباه در نام یا BSN می‌تواند برای معاش یا مالیهٔ شما مشکل پیدا کند. آدرس یا نمبر تیلفون جدید دارید؟ به کارفرمای خود بگویید.",
