    'c.dates.o2': "فقط ۳ و ۴ جون.",
    'c.dates.o3': "از ۶ مارچ تا ۶ مِی.",
    'c.dates.w': "اول روز می‌آید، بعد ماه: 3-6 یعنی ۳ جون. «Tot en met» یعنی ۵ جون هم حساب است، پس سه روز رخصت هستید.",
    'c.permit': "کار و دورهٔ ادغام",
    'c.permit.b': "باید دورهٔ ادغام (inburgering) را بگذرانید؟ به کارفرمای خود بگویید، و به شاروالی (gemeente) بگویید که کار می‌کنید. زود بپرسید که آیا درس‌های زبان با تقسیم اوقات کار شما جور می‌آید. مطمئن نیستید که اجازه دارید اینجا کار کنید؟ پیش از شروع کنترول کنید، مثلاً در IND، UWV یا VluchtelingenWerk. از شما می‌خواهند که برای این کار به حیث کارگر آزاد (zzp’er) ثبت نام کنید؟ اول مشوره بگیرید. معلومات عمومی. برای وضعیت خود تان: از کارفرما، اتحادیهٔ کارگری یا Juridisch Loket بپرسید.", // nieuw, nalezen (AI-correctie 2 nov 2026)
    'c.permit.p': "سه‌شنبه‌ها درس زبان دارم. آیا تقسیم اوقات کارم می‌تواند این را در نظر بگیرد؟",
    'c.permit.s': "درس زبان شما سه‌شنبه صبح است. مطابق تقسیم اوقات جدید، همان وقت کار می‌کنید. چه می‌کنید؟", // nieuw, nalezen (AI-correctie 2 nov 2026)
    'c.permit.o1': "از سرپرست خود بخواهید که تقسیم اوقات را تغییر بدهد.", // nieuw, nalezen (AI-correctie 2 nov 2026)
    'c.permit.o2': "به درس نروید: کار اول است.", // nieuw, nalezen (AI-correctie 2 nov 2026)
    'c.permit.o3': "سه‌شنبه‌ها بدون اینکه چیزی بگویید در خانه بمانید.",
    'c.permit.w': "دورهٔ ادغام هم یک وجیبه است. بسیاری از کارفرمایان اگر زود بدانند کمک می‌کنند. شاروالی (gemeente) هم می‌تواند کمک کند که پلان خود را با کار تان جور کنید.",
    'c.kids': "طفل شما مریض است",
    'c.kids.b': "طفل شما ناگهان مریض شده؟ فوراً به کارفرمای خود بگویید. برای ساعت‌ها یا روزهای اول می‌توانید رخصتی عاجل (calamiteitenverlof) بگیرید، و کارفرما معاش شما را همچنان می‌پردازد. طفل شما مدت بیشتری به مراقبت ضرورت دارد؟ آن وقت می‌توانید رخصتی مراقبت (zorgverlof) بخواهید. حامله هستید؟ کارفرما اجازه ندارد به این خاطر شما را از کار برکنار کند. به وقتش دربارهٔ رخصتی حاملگی و رخصتی والدین (ouderschapsverlof) بپرسید. معلومات عمومی. برای وضعیت خود تان: از کارفرما، اتحادیهٔ کارگری یا Juridisch Loket بپرسید.",
