    's.food.2': "دستکش‌های ضد برش کجاست؟", // nieuw, nalezen
    's.food.3': "در اتاق انجماد یک جاکت گرم می‌پوشم.", // nieuw, nalezen
    'c.food.q': "چرا حالا خط را پاک می‌کنیم؟", // nieuw, nalezen
    'c.food.a': "بعد یک محصول بدون مغزیات می‌آید.", // nieuw, nalezen
    'c.food': "دست‌های پاک، غذای مصئون", // nieuw, nalezen
    'c.food.b': "کار با مواد خوراکی مقررات سخت حفظ الصحه دارد: جالی موی، لباس کار پاک، دست‌های شسته و بدون زیورات. این مقررات برای همه یکسان است. این‌ها دربارهٔ شما چیزی نمی‌گویند: غذا را برای کسانی که آن را می‌خورند مصئون نگه می‌دارند. با چاقو همیشه دستکش ضد برش خود را بپوشید. در اتاق سرد یا اتاق انجماد، لباس‌های گرمی را که به شما می‌دهند بپوشید، و در وقت تفریح خود را گرم کنید. مریض هستید، یا در دست خود زخم دارید؟ پیش از شروع کار خبر بدهید. آن وقت می‌توانید یک پلستر خاص بگیرید، یا برای مدتی کار دیگری. مقررات در هر کمپنی فرق می‌کند: از سرپرست خود بپرسید که مقررات جای کار شما چیست.", // nieuw, nalezen
    'c.food.p': "دستم کمی بریده. می‌توانم یک پلستر بگیرم؟", // nieuw, nalezen
    'c.food.s': "در خانه انگشت تان کمی بریده. امروز با گوشت کار می‌کنید. چه می‌کنید؟", // nieuw, nalezen
    'c.food.o1': "به سرپرست خود بگویید و یک پلستر بخواهید.", // nieuw, nalezen
