    'c.food.o3': "بالای آن دستکش بپوشید تا کسی آن را نبیند.", // nieuw, nalezen
    'c.food.w': "یک زخم کوچک می‌تواند میکروب را داخل غذا ببرد. وقتی خبر بدهید، می‌توانید یک پلستر خاص یا برای مدتی کار دیگری بگیرید. خبر دادن آن عادی است: هیچ کس شما را به خاطر آن ملامت نمی‌کند.", // nieuw, nalezen
