    'w.meten': "اندازه کردن", // nieuw, nalezen
    'w.rechtlijn': "راست (کج نی)", // nieuw, nalezen
    'w.plank': "تختهٔ چوبی", // nieuw, nalezen
    'w.schroef': "پیچ", // nieuw, nalezen
    's.measure.1': "این تختهٔ چوبی چقدر دراز است؟", // nieuw, nalezen
    's.measure.2': "دیوار راست نیست.", // nieuw, nalezen
    's.measure.3': "آن را دو بار اندازه می‌کنم.", // nieuw, nalezen
    'c.measure.q': "بر آن باید چقدر باشد؟", // nieuw, nalezen
    'c.measure.a': "نود سانتی‌متر. آن را نوشته می‌کنم.", // nieuw, nalezen
    'c.measure': "دو بار اندازه کنید، یک بار اره کنید", // nieuw, nalezen
    'c.measure.b': "در ساحهٔ ساختمانی، اندازه‌ها اکثراً به ملی‌متر است. پس «نه صد» می‌تواند ۹۰ سانتی‌متر باشد. مطمئن نیستید؟ بپرسید: «این ملی‌متر است یا سانتی‌متر؟» عدد را دوباره بگویید، و آن را نوشته کنید. پیش از اره کردن یا برمه کردن دو بار اندازه کنید: تخته‌ای که کوتاه است، کوتاه می‌ماند. اشتباه کردید؟ فوراً بگویید. آن وقت تیم هنوز می‌تواند آن را جور کند، و مصرفش کمتر است.", // nieuw, nalezen
    'c.measure.p': "این به ملی‌متر است یا به سانتی‌متر؟", // nieuw, nalezen
    'c.measure.s': "همکار شما یک اندازه را صدا می‌کند. شما آن را خوب نشنیدید. چه می‌کنید؟", // nieuw, nalezen
    'c.measure.o1': "عدد را دوباره بگویید، و بپرسید که درست است یا نی.", // nieuw, nalezen
    'c.measure.o2': "تخته را به همان اندازه‌ای که فکر می‌کنید شنیدید اره کنید.", // nieuw, nalezen
    'c.measure.o3': "صبر کنید تا خودش بیاید و ببیند.", // nieuw, nalezen
    'c.measure.w': "یک اندازهٔ غلط مواد و وقت را ضایع می‌کند. دوباره گفتن عدد دو ثانیه وقت می‌گیرد، و در ساحهٔ ساختمانی همه این کار را می‌کنند.", // nieuw, nalezen
