    'c.colours': "هر رنگ جای خود را دارد", // nieuw, nalezen
    'c.colours.b': "بسیاری کمپنی‌های پاک‌کاری با رنگ‌ها کار می‌کنند. هر رنگ تکه، اسفنج و بالتی برای یک جای است. اکثراً سرخ برای تشناب است، و آبی برای میزها. این طور چتلی تشناب به میز کار یا آشپزخانه نمی‌رسد. رنگ‌ها در هر کمپنی می‌تواند فرق داشته باشد، پس در روز اول خود بپرسید. یک تکه چتل است، یا به زمین افتاده؟ یک تکهٔ پاک بگیرید. تکه‌های استفاده‌شده در خریطهٔ کالاشویی می‌رود، نه دوباره سر کراچی. مقررات در هر کمپنی فرق می‌کند: از سرپرست خود بپرسید که مقررات جای کار شما چیست.", // nieuw, nalezen
