    'c.shophelp': "«نمی‌دانم» آخر گپ نیست", // nieuw, nalezen
    'c.shophelp.b': "یک مشتری چیزی می‌پرسد و شما جوابش را نمی‌دانید. مشکلی نیست: هیچ کس همه چیز را نمی‌داند. اما فقط «nee» یا «weet ik niet» نگویید، و همین طور نروید. بگویید: «Ik vraag het even voor u»، و یک همکار را بیاورید. یک محصول خلاص شده؟ بگویید که چه وقت دوباره می‌آید، یا چیزی مثل آن را نشان بدهید. به مشتری نگاه کنید و سلام بدهید، حتی وقتی به پر کردن رف‌ها مصروف هستید. سوال را نفهمیدید؟ از مشتری بخواهید که آن را دوباره بگوید، آهسته.", // nieuw, nalezen
