    'c.shophelp.w': "برای مشتری مهم نیست که شما نو هستید یا هنوز هالندی یاد می‌گیرید. برای مشتری مهم است که کمک نگیرد. آوردن یک همکار خدمت خوب است.", // nieuw, nalezen
