    'c.shoptrouble.q': "من همین حالا پول خود را پس می‌خواهم!", // nieuw, nalezen
    'c.shoptrouble.a': "می‌فهمم. همکارم را می‌آورم.", // nieuw, nalezen
    'c.shoptrouble': "مشتری قهر یا دزد: اول خود شما", // nieuw, nalezen
    'c.shoptrouble.b': "گاهی یک مشتری قهر می‌شود، یا می‌بینید که کسی دزدی می‌کند. مصئونیت شما اول است، همیشه. با مشتری قهر: آرام بمانید، در جواب چیغ نزنید، و آمر دکان را بیاورید. لازم نیست آن را به تنهایی حل کنید. دزد می‌بینید؟ پشتش ندوید، او را نگیرید، و پیش دروازه را بند نکنید. خوب ببینید که چه می‌بینید، و فوراً به آمر دکان یا محافظ امنیتی بگویید. جنس‌ها را می‌شود دوباره خرید. شما را نمی‌شود. بعد از آن ترسیده بودید؟ با سرپرست خود دربارهٔ آن گپ بزنید. مقررات در هر کمپنی فرق می‌کند: از سرپرست خود بپرسید که مقررات جای کار شما چیست.", // nieuw, nalezen
