    'c.shoptrouble.s': "یک مرد یک بوتل را زیر کرتی خود می‌ماند و طرف دروازهٔ خروجی می‌رود. چه می‌کنید؟", // nieuw, nalezen
    'c.shoptrouble.o1': "به آمر دکان یا محافظ بگویید.", // nieuw, nalezen
    'c.shoptrouble.o2': "پشتش بدوید و بازویش را بگیرید.", // nieuw, nalezen
    'c.shoptrouble.o3': "پیش دروازه ایستاد شوید.", // nieuw, nalezen
    'c.shoptrouble.w': "دزدی که او را ایستاد کنند می‌تواند خشن شود. آمر دکان و محافظ می‌دانند که چه کنند. هیچ جنسی ارزش زخمی شدن شما را ندارد.", // nieuw, nalezen
