    'c.plantcare': "دست‌های پاک، نبات‌های صحتمند", // nieuw, nalezen
    'c.plantcare.b': "نبات‌ها هم مریض می‌شوند. ویروس با دست، دستکش، چاقو و لباس از یک نبات به نبات دیگر می‌رود. در گلخانه، یک نبات مریض می‌تواند باعث شود که هزاران نبات دور انداخته شود. به همین خاطر پیش دروازه مقررات سخت است: دست‌های خود را بشویید، لباس کار کمپنی را بپوشید، و از حوضچهٔ پای تیر شوید. بسیاری گلخانه‌ها اجازه نمی‌دهند که در نان چاشت تان بادنجان رومی، مرچ دلمه‌ای یا بادرنگ خود تان باشد. نباتی می‌بینید که عجیب معلوم می‌شود؟ به آن دست نزنید. به سرپرست خود بگویید که در کدام قطار است. مقررات در هر کمپنی فرق می‌کند: از سرپرست خود بپرسید که مقررات جای کار شما چیست.", // nieuw, nalezen
