    'c.outdoors': "آفتاب، باران و رعد و برق", // nieuw, nalezen
    'c.outdoors.b': "در بیرون در هر رقم هوا کار می‌کنید. در آفتاب: سر و پوست خود را بپوشانید، کریم ضد آفتاب بزنید، و زود زود آب بنوشید. در باران: لباس بارانی و موزه‌های خود را بپوشید، و در وقت تفریح لباس خشک بپوشید. تری و سردی شما را مریض و سست می‌کند. رعد و برق است؟ پس کار را بس کنید و داخل بروید، یا داخل یک موتر یا موتر وان. نه زیر درخت، و نه در زمین باز. برای کار به لباس بارانی یا موزه ضرورت دارید؟ پیش از اینکه خود تان بخرید از کارفرمای خود دربارهٔ آن بپرسید.", // nieuw, nalezen
