    'c.drawing.b': "در ورکشاپ چیزی را می‌سازید که در نقشه است، نه چیزی را که تقریباً درست معلوم می‌شود. اندازه‌ها به ملی‌متر است، و یک ملی‌متر می‌تواند زیاد باشد. یک پرزه جور نمی‌آید؟ زور نزنید، و سوراخ را «فقط کمی» کلان نکنید. دوباره اندازه کنید، و به نقشه ببینید. نقشه را خوانده نمی‌توانید، یا یک اندازه کم است؟ پیش از شروع بپرسید. یک سوال یک دقیقه وقت می‌گیرد. یک پرزهٔ غلط مواد و ساعت‌ها وقت را ضایع می‌کند.", // nieuw, nalezen
