    'c.weld.b': "ولدنگ روشنی بسیار تیز می‌دهد. بدون ماسک ولدنگ به آن نگاه نکنید، حتی از دور: چشم‌های تان می‌سوزد، و شما تازه چند ساعت بعد آن را حس می‌کنید. یک همکار نزدیک شما ولدنگ می‌کند؟ روی خود را دور بدهید، یا پشت پرده ایستاد شوید. فلزی که تازه ولدنگ یا سنگ زده شده عادی معلوم می‌شود، اما بسیار داغ است. آن را با دست لچ برندارید. دود ولدنگ برای شش‌های تان بد است: دودکش را روشن کنید. سوختگی دارید؟ فوراً آن را با آب سرد کنید، دست کم ده دقیقه، و خبر بدهید. مقررات در هر کمپنی فرق می‌کند: از سرپرست خود بپرسید که مقررات جای کار شما چیست.", // nieuw, nalezen
    'c.weld.p': "این سرد شده؟", // nieuw, nalezen
    'c.weld.s': "یک همکار پهلوی شما ولدنگ می‌کند. شما ماسک ولدنگ نپوشیده‌اید. چه می‌کنید؟", // nieuw, nalezen
    'c.weld.o1': "روی خود را دور بدهید، و پشت پرده ایستاد شوید.", // nieuw, nalezen
    'c.weld.o2': "کمی تماشا کنید: از آن چیزی یاد می‌گیرید.", // nieuw, nalezen
    'c.weld.o3': "چشم‌های خود را نیمه بسته کنید.", // nieuw, nalezen
    'c.weld.w': "روشنی ولدنگ چشم‌های شما را می‌سوزاند، حتی از پهلو و از دور. درد را تازه بعداً حس می‌کنید، اکثراً در شب.", // nieuw, nalezen
    'l.carparts': "پرزه‌های موتر", // nieuw, nalezen
