    'w.rem': "بریک", // nieuw, nalezen
    'w.lamp': "چراغ", // nieuw, nalezen
    'w.ruitenwisser': "برف‌پاک", // nieuw, nalezen
    'w.stoel': "چوکی، سیت", // nieuw, nalezen
    's.carparts.1': "بانت را باز کنید.", // nieuw, nalezen
    's.carparts.2': "چراغ پیش، طرف چپ، خراب است.", // nieuw, nalezen
    's.carparts.3': "بریک‌ها صدا می‌کند.", // nieuw, nalezen
    'c.carparts.q': "چه می‌شنوید؟", // nieuw, nalezen
    'c.carparts.a': "ماشین موتر یک صدای عجیب می‌دهد.", // nieuw, nalezen
    'c.carparts': "موتر از مشتری است", // nieuw, nalezen
    'c.carparts.b': "موتری که در ورکشاپ است از شما نیست: از مشتری است. پیش از اینکه سوار شوید یک پوش سر سیت و سر اشترنگ بکشید، و در داخل با دست‌های پاک کار کنید. سیت، آینه‌ها و رادیو را همان طور که بود بگذارید. مجبور شدید سیت را پس و پیش کنید؟ آن را دوباره به جایش بیاورید. به چیزهای شخصی داخل موتر دست نزنید. یک خراش یا لکه انداختید؟ فوراً به سرپرست خود بگویید. مشتری‌ای که آن را در خانه ببیند دیگر پس نمی‌آید.", // nieuw, nalezen
    'c.carparts.p': "من یک خراش انداختم. ببخشید.", // nieuw, nalezen
    'c.carparts.s': "سر دروازهٔ موتر یک مشتری یک خراش کوچک می‌اندازید. هیچ کس ندید. چه می‌کنید؟", // nieuw, nalezen
    'c.carparts.o1': "فوراً به سرپرست خود بگویید.", // nieuw, nalezen
    'c.carparts.o2': "چیزی نگویید: بسیار کوچک است.", // nieuw, nalezen
    'c.carparts.o3': "با یک تکه آن را پاک کنید، و امید کنید که برود.", // nieuw, nalezen
    'c.carparts.w': "همه گاهی اشتباه می‌کنند. ورکشاپ می‌تواند خراش را ترمیم کند، یا صادقانه به مشتری بگوید. یک خراش پنهان، نام نیک ورکشاپ را خراب می‌کند.", // nieuw, nalezen
    'l.carsafe': "پطرول، گاز و برق", // nieuw, nalezen
    'w.krik': "جک (یک طرف موتر را بلند می‌کند)", // nieuw, nalezen
    'w.benzine': "پطرول", // nieuw, nalezen
    'w.elektrischeauto': "موتر برقی", // nieuw, nalezen
    'w.oranje': "نارنجی", // nieuw, nalezen
    'w.morsen': "ریختاندن (بی‌هوا ریختن)", // nieuw, nalezen
    'w.lap': "لته (تکه‌ای برای کار چتل)", // nieuw, nalezen
    's.carsafe.1': "بوی پطرول می‌آید.", // nieuw, nalezen
    's.carsafe.2': "روغن ریخته. یک لته می‌آورم.", // nieuw, nalezen
    's.carsafe.3': "به کیبل‌های نارنجی دست نمی‌زنم.", // nieuw, nalezen
    'c.carsafe.q': "اجازه است سر این موتر کار کنم؟", // nieuw, nalezen
    'c.carsafe.a': "هنوز نی. این موتر برقی است.", // nieuw, nalezen
    'c.carsafe': "کیبل‌های نارنجی و ماشین روشن", // nieuw, nalezen
    'c.carsafe.b': "موتر برقی یا هایبرید یک بتری با برق بسیار قوی دارد. کیبل‌های آن نارنجی است. به آن‌ها دست نزنید و آن‌ها را باز نکنید: اول باید یک میخانیک که آموزش خاص دیده موتر را مصئون کند. پیش موتر یک تخته یا یک مخروط ترافیکی است؟ پس دور بمانید. ماشین موتری که در داخل روشن است گازی جور می‌کند که نه بویش می‌آید و نه دیده می‌شود، و می‌تواند آدم را بکشد. پس: پایپ اگزاست را وصل کنید، یا دروازه‌ها را باز کنید. بوی پطرول می‌آید؟ نه جرقه و نه سگرت. فوراً به سرپرست خود بگویید. مقررات در هر کمپنی فرق می‌کند: از سرپرست خود بپرسید که مقررات جای کار شما چیست.", // nieuw, nalezen
    'c.carsafe.p': "این موتر مصئون شده؟", // nieuw, nalezen
    'c.carsafe.s': "باید تایر یک موتر برقی را عوض کنید. زیر موتر یک کیبل نارنجی را می‌بینید که آویزان است. چه می‌کنید؟", // nieuw, nalezen
    'c.carsafe.o1': "به هیچ چیز دست نزنید، و میخانیک آموزش‌دیده را بیاورید.", // nieuw, nalezen
    'c.carsafe.o2': "کیبل را با دست پس تیله کنید.", // nieuw, nalezen
    'c.carsafe.o3': "آن را با یک تکهٔ خشک پس تیله کنید.", // nieuw, nalezen
    'c.carsafe.w': "بتری موتر برقی آن قدر برق دارد که آدم را بکشد، حتی وقتی موتر خاموش است. فقط کسی که آموزش دیده اجازه دارد به این پرزه‌ها دست بزند.", // nieuw, nalezen
