    'w.spiegel': "آینه", // nieuw, nalezen
    'w.tanken': "تیل انداختن (در موتر تیل انداختن)", // nieuw, nalezen
    'w.opladen': "چارج کردن (موتر برقی، تیلفون)", // nieuw, nalezen
    'w.parkeren': "پارک کردن", // nieuw, nalezen
    's.vancheck.1': "در دروازه یک فرورفتگی است.", // nieuw, nalezen
    's.vancheck.2': "این خساره از پیش بود.", // nieuw, nalezen
    's.vancheck.3': "اول باید تیل بیندازم.", // nieuw, nalezen
    'c.vancheck.q': "همه چیز موتر خوب است؟", // nieuw, nalezen
    'c.vancheck.a': "نی، آینه شکسته است.", // nieuw, nalezen
    'c.vancheck': "پیش از راندن نگاه کنید", // nieuw, nalezen
    'c.vancheck.b': "پیش از دور اول خود، گرد موتر قدم بزنید. یک فرورفتگی، یک خراش یا یک آینهٔ شکسته را می‌بینید؟ یک عکس بگیرید، و پیش از حرکت گزارش بدهید. آن وقت همه می‌دانند که خساره از پیش بود. در جریان دور شما چیزی شد؟ همان روز گزارش بدهید، حتی اگر کوچک باشد. پنهان کردن خساره بعداً مشکلات کلان‌تر جور می‌کند. مقررات در هر کمپنی فرق می‌کند: از سرپرست خود بپرسید که مقررات جای کار شما چیست.", // nieuw, nalezen
    'c.vancheck.p': "موتر خساره دارد. این هم یک عکس.", // nieuw, nalezen
    'c.vancheck.s': "صبح یک فرورفتگی نو را در موتر می‌بینید. شما آن را نکرده‌اید. چه می‌کنید؟", // nieuw, nalezen
    'c.vancheck.o1': "یک عکس بگیرید، و پیش از حرکت گزارش بدهید.", // nieuw, nalezen
    'c.vancheck.o2': "چیزی نگویید: کار شما نیست.", // nieuw, nalezen
    'c.vancheck.o3': "صبر کنید و ببینید که کسی دربارهٔ آن می‌پرسد یا نی.", // nieuw, nalezen
    'c.vancheck.w': "وقتی پیش از حرکت گزارش بدهید، هیچ کس نمی‌تواند فکر کند که شما این کار را کرده‌اید. عکسی که ساعت دارد برای همه روشن است.", // nieuw, nalezen
    'l.delay': "ناوقتی در سرک", // nieuw, nalezen
    'w.file': "راه‌بندی، بیروبار ترافیک", // nieuw, nalezen
