    'w.retour': "بستهٔ برگشتی (بسته‌ای که پس می‌رود)", // nieuw, nalezen
    's.delay.1': "در راه‌بندی مانده‌ام.", // nieuw, nalezen
    's.delay.2': "نیم ساعت تأخیر دارم.", // nieuw, nalezen
    's.delay.3': "این بسته پس می‌رود.", // nieuw, nalezen
    'c.delay.q': "حالا کجا هستید؟", // nieuw, nalezen
    'c.delay.a': "پیش راه بدیل. ده دقیقه ناوقت‌تر می‌رسم.", // nieuw, nalezen
    'c.delay': "ناوقت می‌رسید؟ به وقت بگویید", // nieuw, nalezen
    'c.delay.b': "راه‌بندی یا سرک بسته تقصیر شما نیست. اما همین که فهمیدید ناوقت می‌رسید، به پلان‌گذار بگویید. آن وقت پلان‌گذار می‌تواند به مشتری‌ها بگوید، یا مسیر را تغییر بدهد. اول در یک جای مصئون ایستاد شوید: در وقت موتر راندن با تیلفون در دست زنگ نزنید. و برای پس گرفتن وقت تیزتر نرانید. مقررات در هر کمپنی فرق می‌کند: از سرپرست خود بپرسید که مقررات جای کار شما چیست.", // nieuw, nalezen
    'c.delay.p': "در راه‌بندی مانده‌ام. نیم ساعت ناوقت‌تر می‌رسم.", // nieuw, nalezen
    'c.delay.s': "یک سرک بسته است. راه بدیل سی دقیقه وقت شما را می‌گیرد. چه می‌کنید؟", // nieuw, nalezen
    'c.delay.o1': "همین که توانستید مصئون ایستاد شوید، به پلان‌گذار بگویید.", // nieuw, nalezen
    'c.delay.o2': "تیزتر برانید تا وقت را پس بگیرید.", // nieuw, nalezen
    'c.delay.o3': "چیزی نگویید: شاید کسی نفهمد.", // nieuw, nalezen
    'c.delay.w': "وقتی پلان‌گذار وقت بداند، مشتری‌ها خبر می‌شوند و هیچ کس بی‌فایده منتظر نمی‌ماند. تیز راندن خطرناک است، و تقریباً هیچ وقت را پس نمی‌گیرد.", // nieuw, nalezen
    // "Instructies", a new basis unit (u.do, 14 November 2026).
