    's.tiletools.1': "کرندی دندانه‌دار را یک لحظه به من بدهید.", // nieuw, nalezen
    's.tiletools.2': "کاشی را با کاشی‌بُر می‌بُرم.", // nieuw, nalezen
    's.tiletools.3': "اول با متر قات‌شونده اندازه کنید.", // nieuw, nalezen
    'c.tiletools.q': "مکسر کجاست؟", // nieuw, nalezen
    'c.tiletools.a': "پیش بالتی، پهلوی دروازه.", // nieuw, nalezen
    'c.tiletools': "افزار تان را پیش از سخت شدن چسپ پاک کنید", // nieuw, nalezen
    'c.tiletools.b': "چسپ کاشی و گچ زود سخت می‌شوند، بالای افزار شما هم. پس کرندی دندانه‌دار، کرندی و مکسر را فوراً در یک بالتی آب پاک کنید، پیش از تفریح تان هم. چسپ سخت‌شده پاک نمی‌شود، و کرندی دندانه‌داری که چسپ سخت بالایش باشد، خط‌های بد می‌سازد. آب چتل را در دستشوی یا جوی نریزید: بند می‌شود. بپرسید که آب کجا ریخته شود. مکسر: آن را با دو دست بگیرید، و آهسته روشن کنید. مقررات در هر کمپنی فرق می‌کند: از سرپرست خود بپرسید که مقررات جای کار شما چیست.", // nieuw, nalezen
    'c.tiletools.p': "کرندی دندانه‌دار را پاک می‌کنم.", // nieuw, nalezen
    'c.tiletools.s': "وقت تفریح تان است. کرندی دندانه‌دار شما پر از چسپ تر است. چه می‌کنید؟", // nieuw, nalezen
    'c.tiletools.o1': "آن را در آب پاک کنید، بعد تفریح کنید.", // nieuw, nalezen
    'c.tiletools.o2': "بگذارید: بعد از کار پاکش کنید.", // nieuw, nalezen
    'c.tiletools.o3': "آن را در بالتی چسپ بگذارید.", // nieuw, nalezen
    'c.tiletools.w': "چسپ کاشی در وقت تفریح هم سخت می‌شود. کرندی دندانه‌دار پاک خط‌های خوب می‌سازد، و کاشی‌ها خوب می‌چسپند. چسپ سخت بالای آن یعنی کار زیاد، یا یک افزار نو.", // nieuw, nalezen
    'l.tiling': "کاشی، چسپ و خط وسط", // nieuw, nalezen
