    's.tiling.1': "چسپ کاشی هنوز تر است.", // nieuw, nalezen
    's.tiling.2': "یک صلیبک را میان کاشی‌ها بگذارید.", // nieuw, nalezen
    's.tiling.3': "اول خط وسط را با پنسل بکشید.", // nieuw, nalezen
    'c.tiling.q': "با کاشی‌ها از کجا شروع کنم؟", // nieuw, nalezen
    'c.tiling.a': "در وسط، بالای خط وسط.", // nieuw, nalezen
    'c.tiling': "از خط وسط شروع کنید، با کمی چسپ", // nieuw, nalezen
    'c.tiling.b': "یک کاشی‌کار از کنج شروع نمی‌کند. اول خط وسط را با پنسل و آب‌ترازو می‌کشید، و از همان‌جا شروع می‌کنید. آن وقت کاشی‌های بریده در هر دو سر یک اندازه می‌شوند. فقط آن قدر چسپ پهن کنید که بتوانید زود با کاشی بپوشانید. چسپی که زیاد بماند، یک پوست خشک می‌گیرد، و آن وقت کاشی‌ها خوب نمی‌چسپند. هر جایی که درزها به هم می‌رسند یک صلیبک بگذارید، تا همهٔ درزها یک اندازه باشند. زیاد با آب‌ترازو ببینید: کاشی کج را حالا به آسانی جور کرده می‌توانید، و فردا به مشکل.", // nieuw, nalezen
    'c.tiling.p': "یک دفعه چسپ زیاد پهن نمی‌کنم.", // nieuw, nalezen
    'c.tiling.s': "بعد از یک زنگ طولانی، چسپ روی دیوار یک پوست خشک گرفته. چه می‌کنید؟", // nieuw, nalezen
    'c.tiling.o1': "آن را بتراشید، و چسپ تازه پهن کنید.", // nieuw, nalezen
    'c.tiling.o2': "کاشی‌ها را باز هم بالایش فشار بدهید.", // nieuw, nalezen
    'c.tiling.o3': "با اسفنج ترش کنید، و ادامه بدهید.", // nieuw, nalezen
    'c.tiling.w': "چسپی که پوست خشک دارد، کاشی را خوب نگه نمی‌کند. بعداً کاشی شاید جدا شود، و آن وقت کار باید دوباره شود.", // nieuw, nalezen
    'l.plaster': "گچ‌کاری", // nieuw, nalezen
