    's.plaster.2': "دیوار را با مالهٔ گچ صاف کنید.", // nieuw, nalezen
    's.plaster.3': "شمشه را بالای دیوار بکشید.", // nieuw, nalezen
    'c.plaster.q': "دیوار خشک شده؟", // nieuw, nalezen
    'c.plaster.a': "نی، یک روز دیگر صبر کنید.", // nieuw, nalezen
    'c.plaster': "گچ برای خشک شدن وقت می‌خواهد", // nieuw, nalezen
    'c.plaster.b': "گچ تازه مدت زیاد تر می‌ماند. یک دیوار تر، از یک دیوار خشک تاریک‌تر است. رنگمال فقط وقتی شروع کرده می‌تواند که دیوار در همه جا خشک باشد، و این شاید چند روز یا چند هفته وقت بگیرد. آن را با بخاری زودتر خشک نکنید: آن وقت گچ شاید ترک بردارد. کسی می‌خواهد خیلی زود رنگ کند؟ بگویید که دیوار هنوز خشک نیست. و پیش از شروع کار، زمین، کلکین‌ها و ساکت‌های برق را بپوشانید: گچ به مشکل پاک می‌شود.", // nieuw, nalezen
    'c.plaster.p': "دیوار هنوز تر است. هنوز رنگ کرده نمی‌توانید.", // nieuw, nalezen
    'c.plaster.s': "رنگمال می‌خواهد فردا شروع کند. گچ تازه هنوز داغ‌های تاریک دارد. چه می‌کنید؟", // nieuw, nalezen
    'c.plaster.o1': "به رنگمال بگویید: دیوار هنوز خشک نیست.", // nieuw, nalezen
    'c.plaster.o2': "امشب یک بخاری پیش رویش بگذارید.", // nieuw, nalezen
    'c.plaster.o3': "چیزی نگویید: رنگمال خودش می‌بیند.", // nieuw, nalezen
    'c.plaster.w': "داغ‌های تاریک یعنی گچ هنوز تر است. رنگ بالای دیوار تر شاید جدا شود، و بخاری شاید ترک بیندازد. صبر کردن از دوباره کردن کار ارزان‌تر است.", // nieuw, nalezen
