    'c.shapes': "مستطیل را با دو خط چپ و راست امتحان کنید", // nieuw, nalezen
    'c.shapes.b': "یک اتاق، یک فرش یا یک چوکات اکثراً مستطیل است. اما آیا کنج‌ها واقعاً راست است؟ یک امتحان ساده است. از یک کنج تا کنج روبرو اندازه کنید. بعد میان دو کنج دیگر اندازه کنید. هر دو اندازه یکی است؟ پس کنج‌ها درست است. یکی نیست؟ پس شکل کمی کج است، و کاشی یا فرش خوب جور نمی‌آید. پیش از شروع به سرپرست خود بگویید.", // nieuw, nalezen
