    'c.angles.a': "چهل و پنج. نیم یک زاویهٔ راست.", // nieuw, nalezen
    'c.angles': "یک کنج کلان را با ۳، ۴ و ۵ امتحان کنید", // nieuw, nalezen
    'c.angles.b': "در ساحهٔ ساختمانی اکثراً یک زاویهٔ راست را امتحان می‌کنید: یک دیوار بالای فرش، یک کنج اتاق. یک کنج خورد را با گونیا امتحان می‌کنید. برای یک کنج کلان یک راه قدیمی است. در یک طرف ۳ متر و در طرف دیگر ۴ متر اندازه کنید، و در هر دو جای نشانی بگذارید. از نشانی تا نشانی درست ۵ متر است؟ پس زاویه ۹۰ درجه است. خوردتر هم می‌شود: ۳۰، ۴۰ و ۵۰ سانتی‌متر.", // nieuw, nalezen
    'c.angles.p': "این زاویه راست نیست.", // nieuw, nalezen
    'c.angles.s': "باید کنج کلان یک دیوار نو را امتحان کنید. گونیای شما خیلی خورد است. چه می‌کنید؟", // nieuw, nalezen
    'c.angles.o1': "۳، ۴ و ۵ متر اندازه کنید.", // nieuw, nalezen
    'c.angles.o2': "از دور به آن نگاه کنید.", // nieuw, nalezen
    'c.angles.o3': "باز هم گونیای خورد را استفاده کنید.", // nieuw, nalezen
    'c.angles.w': "با ۳، ۴ و ۵ یک کنج کلان را دقیق امتحان کرده می‌توانید، فقط با یک فیتهٔ متر. به چشم، یک کنج شاید درست معلوم شود و باز هم غلط باشد.", // nieuw, nalezen
