    'c.size.b': "چند کاشی، چقدر رنگ، چقدر ریگ؟ این را با مساحت یا حجم حساب می‌کنید. مساحت: درازی ضرب بر، به متر مربع. حجم: درازی ضرب بر ضرب بلندی، به متر مکعب. همه چیز را به یک واحد اندازه کنید: همه به متر، یا همه به سانتی‌متر. اندازه‌ها را نوشته کنید، در یاد خود نگه ندارید. بعد کمی اضافه بگیرید، برای تکه‌های بریده و برای اشتباه. مطمئن نیستید؟ از یک همکار بخواهید که حساب تان را ببیند.", // nieuw, nalezen
    'c.size.p': "اندازه‌ها را نوشته می‌کنم.", // nieuw, nalezen
    'c.size.s': "شما فرش را اندازه کردید. باید امروز کاشی‌ها را فرمایش بدهید. چه می‌کنید؟", // nieuw, nalezen
