    'c.size.o2': "همان مساحت را فرمایش بدهید، یک کاشی هم زیادتر نی.", // nieuw, nalezen
    'c.size.o3': "گمان بزنید: فرش را دیده‌اید.", // nieuw, nalezen
    'c.size.w': "همیشه چند کاشی را می‌بُرید، و چند تا می‌شکند. با کمی اضافه، لازم نیست در نیمهٔ کار ایستاد شوید و دوباره فرمایش بدهید.", // nieuw, nalezen
