    'c.paint.b': "رنگی که مدتی ایستاده، در تَه قطی غلیظ است. پس اول آن را با چوب شور دادن خوب شور بدهید، تا رنگ آن در همه جا یکی شود. از قطی کلان رنگ نکنید: کمی رنگ در سطل خورد بریزید، و قطی را دوباره ببندید. آن وقت رنگ خوب می‌ماند. از بالا به پایین رنگ کنید، تا قطره‌ها بالای رنگ تر بیفتد و هنوز بتوانید آن‌ها را با برس پاک کنید. برس پهن را برای دیوار و برس خورد را برای کنج‌ها استفاده کنید. در آخر، برس‌ها را فوراً پاک کنید.", // nieuw, nalezen
