    'c.prep.q': "حالا رنگ کرده می‌توانم؟", // nieuw, nalezen
    'c.prep.a': "نی، اول ریگمال کنید و سوراخ را پر کنید.", // nieuw, nalezen
    'c.prep': "رنگمالی خوب پیش از رنگ شروع می‌شود", // nieuw, nalezen
    'c.prep.b': "رنگ بالای چتلی، گرد و خاک یا رنگ کهنهٔ سست خوب نمی‌چسپد. پس اول رنگ سست را با رنگ‌تراش بتراشید. سوراخ‌ها را با بتونه و کاردک بتونه پر کنید، و بگذارید بتونه خشک شود. بعد آن را با ریگمال صاف کنید. بعد از ریگمال، گرد و خاک را با برس خورد پاک کنید، از لبه‌ها هم. در آخر، چیزهایی را که باید پاک بمانند با تیپ بپوشانید، مثل کلکین‌ها و ساکت‌های برق. ریگمال کردن گرد بسیار ریزه پیدا می‌کند: ماسک گرد بپوشید، و بپرسید کدام یک. مقررات در هر کمپنی فرق می‌کند: از سرپرست خود بپرسید که مقررات جای کار شما چیست.", // nieuw, nalezen
    'c.prep.p': "اول ریگمال، بعد رنگ.", // nieuw, nalezen
    'c.prep.s': "شما دروازه را ریگمال کردید. هنوز گرد و خاک بالایش است. همکار شما حالا می‌خواهد رنگ کند. چه می‌کنید؟", // nieuw, nalezen
    'c.prep.o1': "اول گرد و خاک را با برس پاک کنید.", // nieuw, nalezen
    'c.prep.o2': "بگذارید رنگ کند: رنگ گرد و خاک را می‌پوشاند.", // nieuw, nalezen
