    'c.brick': "دیوار را در وقت کار پاک نگه دارید", // nieuw, nalezen
    'c.brick.b': "وقتی خشت‌ها را می‌گذارید ملات تر است، و در چند ساعت سخت می‌شود. پس پاک کار کنید. ملاتی را که از درز بیرون می‌آید فوراً با کرندی بتراشید. درزها را وقتی با درزکش صاف کنید که ملات کمی سفت شده، نه وقتی که هنوز تر است. بعد دیوار را با جاروی دستی پاک کنید. ملات سخت در روی خشت به بسیار مشکل پاک می‌شود. در آخر روز، سر دیوار را بپوشانید، تا باران ملات را نشوید.", // nieuw, nalezen
    'c.brick.p': "درزها را صاف می‌کنم.", // nieuw, nalezen
