    'c.brick.o1': "حالا آن را با جارو پاک کنید، پیش از اینکه سخت شود.", // nieuw, nalezen
    'c.brick.o2': "بگذارید: هفتهٔ آینده پاکش می‌کنید.", // nieuw, nalezen
    'c.brick.o3': "دیوار را با آب زیاد بشویید.", // nieuw, nalezen
    'c.brick.w': "ملات تازه با جارو به آسانی پاک می‌شود. ملات سخت بالای خشت می‌ماند، و آن وقت دیوار خوب معلوم نمی‌شود.", // nieuw, nalezen
