    'c.wall': "ریسمان دیوار را راست نگه می‌کند", // nieuw, nalezen
    'c.wall.b': "یک گلکار به چشم کار نمی‌کند. اول پایه‌های کنج در هر دو سر دیوار راست ایستاده می‌شوند. میان آن‌ها ریسمان خشت‌کاری را محکم می‌کشید، به بلندی ردیف بعدی. هر خشت را برابر ریسمان بگذارید، اما ریسمان را تیله نکنید. شمشهٔ ردیف نشان می‌دهد که هر ردیف چقدر بلند باشد. زیاد با آب‌ترازو ببینید. خشت کج را تا ملات تر است به آسانی جور کرده می‌توانید، و فردا به بسیار مشکل.", // nieuw, nalezen
    'c.wall.p': "ریسمان خشت‌کاری محکم است؟", // nieuw, nalezen
    'c.wall.s': "ریسمان خشت‌کاری سست است و در وسط کمی آویزان است. چه می‌کنید؟", // nieuw, nalezen
    'c.wall.o1': "اول آن را محکم بکشید، بعد ادامه بدهید.", // nieuw, nalezen
    'c.wall.o2': "باز هم خشت‌ها را زیر آن بگذارید.", // nieuw, nalezen
    'c.wall.o3': "خشت‌ها را به چشم بگذارید.", // nieuw, nalezen
    'c.wall.w': "ریسمان سست در وسط آویزان می‌شود، پس ردیف هم آویزان می‌شود. ریسمان محکم یک ردیف راست می‌دهد.", // nieuw, nalezen
