    'c.wood': "چوب کوتاه شده دوباره دراز نمی‌شود", // nieuw, nalezen
    'c.wood.b': "چوبی که خیلی کوتاه اره شده، دوباره دراز نمی‌شود. پس دو بار اندازه کنید، و پیش از اره کردن خط را بکشید. پهلوی خط اره کنید، در طرف تکه‌ای که ضرورت ندارید. چوب را محکم نگه دارید: بالای میز کار یا با گیره، نه بالای زانوی خود. بگذارید اره کار کند، با حرکت‌های دراز و آرام. اسکنه را به طرف دور از بدن و دست دیگر خود تیله کنید. و اسکنه و رنده را تیز نگه دارید: افزار کُند زودتر می‌لغزد.", // nieuw, nalezen
    'c.wood.p': "یک بار دیگر اندازه می‌کنم.", // nieuw, nalezen
    'c.wood.s': "باید یک تخته را به اندازه اره کنید. آن را یک بار، با عجله، اندازه کردید. چه می‌کنید؟", // nieuw, nalezen
    'c.wood.o1': "دوباره اندازه کنید، بعد خط را بکشید.", // nieuw, nalezen
    'c.wood.o2': "حالا اره کنید: شاید درست باشد.", // nieuw, nalezen
    'c.wood.o3': "به چشم اره کنید، بدون خط.", // nieuw, nalezen
    'c.wood.w': "دراز را دوباره اره کرده می‌توانید، کوتاه را جور کرده نمی‌توانید. دوباره اندازه کردن یک دقیقه وقت می‌گیرد؛ یک تختهٔ نو خیلی بیشتر.", // nieuw, nalezen
    'l.square': "نشانی کردن", // nieuw, nalezen
