    'c.square': "از یک لبهٔ راست نشانی کنید", // nieuw, nalezen
    'c.square.b': "پیش از اینکه اره یا برمه کنید، جای آن را نشانی می‌کنید. یک پنسل تیز استفاده کنید: خط ضخیم دقیق نیست. یک لبهٔ راست چوب را انتخاب کنید، و همه چیز را از همان لبه اندازه کنید. قسمت ضخیم گونیا را محکم به آن بچسپانید، و خط را برابر فولاد بکشید. بالای تکه‌ای که استفاده نمی‌کنید یک صلیب خورد بکشید. بعد پهلوی خط اره می‌کنید، در طرف صلیب.", // nieuw, nalezen
    'c.square.p': "اول آن را نشانی می‌کنم.", // nieuw, nalezen
    'c.square.s': "پنسل شما کُند است و خط ضخیم می‌کشد. می‌خواهید یک تخته را نشانی کنید. چه می‌کنید؟", // nieuw, nalezen
    'c.square.o1': "اول پنسل را تیز کنید، بعد خط بکشید.", // nieuw, nalezen
    'c.square.o2': "باز هم خط را بکشید، خوب است.", // nieuw, nalezen
    'c.square.o3': "با ناخن خود نشانی کنید.", // nieuw, nalezen
