    'c.fix.b': "یک پیچ یا بولت باید محکم باشد، اما نه خیلی محکم. اگر خیلی زور بدهید، رزوه می‌شکند یا چوب چاک می‌شود. بچرخانید تا دیگر حرکت نکند، بعد بس کنید. در برمهٔ باتری‌دار، اول حلقهٔ نمبردار را به یک نمبر پایین بچرخانید. رفی که به دیوار است رول‌پلاکی می‌خواهد که به دیوار جور بیاید: دیوار سنگی رول‌پلاک دیگری می‌خواهد تا یک دیوار نازک تخته‌ای. چسپ وقت می‌خواهد: تکه‌ها را به هم فشار بدهید، با گیره نگه دارید، و صبر کنید تا چسپ خشک شود.", // nieuw, nalezen
