    'c.atmachine.b': "قسمت‌های متحرک ماشین می‌توانند یک دست، یک آستین یا موی را در کمتر از یک ثانیه به داخل بکشند. پوش محافظ برای همین است. هیچ وقت آن را برندارید، و هیچ وقت وقتی ماشین روشن است دست خود را پشت آن نکنید. یک پوش محافظ یا یک سنسور کار نمی‌کند؟ پس ماشین مصئون نیست: آن را ایستاد کنید و به آمر تیم خود بگویید. چیزی گیر مانده؟ اول ماشین را ایستاد کنید، و مطمئن شوید که وقتی کار می‌کنید هیچ کس آن را روشن کرده نتواند. این کار در هر کمپنی فرق می‌کند: پیش از شروع توضیح بخواهید. مقررات در هر کمپنی فرق می‌کند: از سرپرست خود بپرسید که مقررات جای کار شما چیست.", // nieuw, nalezen
