    'c.packing.b': "بسته‌بندی کار تیز است، و کاتر بسیار تیز است. همیشه به طرف دور از بدن و دور از دست دیگر خود ببُرید. بعد از هر بریدن تیغه را دوباره داخل کنید، حتی وقتی چاقو را یک لحظه پایین می‌گذارید. یک تکهٔ کُند را با احتیاط بشکنید، و آن را در قطی تیغه‌های کهنه بیندازید، نه در سطل عادی کثافات. ماشین سیل و پستول حرارتی برای نایلون حرارتی بسیار داغ می‌شوند: به قسمت‌های داغ دست نزنید. و هر قطی را کنترول کنید: محصول درست، تعداد درست، و لیبل راست. مقررات در هر کمپنی فرق می‌کند: از سرپرست خود بپرسید که مقررات جای کار شما چیست.", // nieuw, nalezen
