    'c.wiring.q': "کدام سیم کجا می‌رود؟", // nieuw, nalezen
    'c.wiring.a': "نصواری به نصواری، آبی به آبی.", // nieuw, nalezen
    'c.wiring': "رنگ‌ها نشان می‌دهند که سیم چه کار می‌کند", // nieuw, nalezen
    'c.wiring.b': "در یک ساختمان، سیم‌ها رنگ‌های ثابت دارند. نصواری (گاهی سیاه یا خاکستری) برق را می‌آورد. آبی پس می‌رود. سبز و زرد ارت است: از مردم محافظت می‌کند، و هیچ وقت برای کار دیگری استفاده نمی‌شود. هر رنگ را به همان رنگ وصل کنید. فقط آن قدر لچ کنید که در کنکتور جای شود: هیچ مس لچ نباید بیرون بماند. سیم را داخل فشار بدهید، بعد آن را آهسته بکشید تا ببینید که محکم است. مطمئن نیستید که کدام سیم کدام است؟ دست نگه دارید و بپرسید.", // nieuw, nalezen
    'c.wiring.p': "ارت کدام رنگ است؟", // nieuw, nalezen
    'c.wiring.s': "شما یک چراغ را وصل می‌کنید. یک تکه مس از کنکتور بیرون مانده. چه می‌کنید؟", // nieuw, nalezen
