    'c.wiring.o2': "بگذارید: چراغ کار می‌کند.", // nieuw, nalezen
    'c.wiring.o3': "یک تکه تیپ دور آن بپیچانید.", // nieuw, nalezen
    'c.wiring.w': "مس لچ بیرون از کنکتور می‌تواند به چیزی بخورد. این می‌تواند برق‌گرفتگی یا شارت ایجاد کند، حتی چند ماه بعد.", // nieuw, nalezen
