    'c.testing.q': "اجازه دارم جعبهٔ فیوز را باز کنم؟", // nieuw, nalezen
    'c.testing.a': "نی، این کار را برقکار می‌کند.", // nieuw, nalezen
    'c.testing': "قطع، قفل، اندازه", // nieuw, nalezen
    'c.testing.b': "پیش از اینکه روی برق کار کنید، سه قدم بردارید. قطع کنید: فیوز درست در جعبهٔ فیوز، نه تنها سویچ روی دیوار. قفل کنید: قفل آویز خود را به آن بزنید و کلید را پیش خود نگه دارید، تا هیچ کس آن را دوباره روشن کرده نتواند. اندازه کنید: با فازمتر یا ملتی‌میتر کنترول کنید که واقعاً برق نیست. تنها بعد از آن شروع کنید. یک فیوز بار بار می‌افتد؟ آن را بار بار روشن نکنید: به سرپرست خود بگویید. تنها وقتی کار برقی کنید که به شما گفته شده که اجازه دارید. مقررات در هر کمپنی فرق می‌کند: از سرپرست خود بپرسید که مقررات جای کار شما چیست.", // nieuw, nalezen
    'c.testing.p': "دیگر برق در آن نیست.", // nieuw, nalezen
    'c.testing.s': "شما فیوز را قطع کردید. یک همکار می‌گوید: «حالا شروع کنید، قطع است.» چه می‌کنید؟", // nieuw, nalezen
    'c.testing.o1': "آن را قفل کنید، و اول اندازه کنید.", // nieuw, nalezen
    'c.testing.o2': "شروع کنید: همکار شما می‌داند.", // nieuw, nalezen
    'c.testing.o3': "برای کنترول، زود به سیم دست بزنید.", // nieuw, nalezen
    'c.testing.w': "گاهی فیوز غلط قطع است، یا کسی آن را دوباره روشن می‌کند. یک قفل و یک اندازه‌گیری نشان می‌دهد که واقعاً مصئون است.", // nieuw, nalezen
