    'c.pipes.q': "اتصال هنوز چکه می‌کند؟", // nieuw, nalezen
    'c.pipes.a': "کمی. آن را کمی دیگر محکم می‌کنم.", // nieuw, nalezen
    'c.pipes': "اول آب بند، و یک سطل آماده", // nieuw, nalezen
    'c.pipes.b': "پیش از اینکه یک نل آب را باز کنید، والو را بند کنید. بعد یک شیر آب پایین‌تر را باز کنید، تا نل خالی شود. یک سطل و یک تکه زیر جایی که کار می‌کنید بگذارید. نل مسی را با نل‌بُر ببُرید، نه با اره: سر نل گرد و پاک می‌ماند. اتصال را محکم کنید، اما نه خیلی زیاد. وقتی کار تان تمام شد، آب را آهسته باز کنید و ببینید که قطره می‌چکد یا نی. یک چکهٔ خورد که آن را بگذارید، به خسارهٔ آب تبدیل می‌شود.", // nieuw, nalezen
    'c.pipes.p': "آب بند است؟", // nieuw, nalezen
    'c.pipes.s': "شما یک اتصال نو ساختید. آب را باز می‌کنید. هر دقیقه یک قطرهٔ خورد می‌چکد. چه می‌کنید؟", // nieuw, nalezen
    'c.pipes.o1': "آب را بند کنید، و آن را محکم‌تر کنید یا از نو بسازید.", // nieuw, nalezen
    'c.pipes.o2': "بگذارید: فقط یک قطره است.", // nieuw, nalezen
    'c.pipes.o3': "یک سطل زیر آن بگذارید و به خانه بروید.", // nieuw, nalezen
    'c.pipes.w': "یک قطره در یک دقیقه، در یک هفته چندین لیتر می‌شود. آب می‌تواند به زمین یا به سقف منزل پایین ضرر برساند.", // nieuw, nalezen
