    's.metalwork.1': "فلز را در گیرهٔ میز کار محکم کنید.", // nieuw, nalezen
    's.metalwork.2': "پلیسه را با سوهان دور کنید.", // nieuw, nalezen
    's.metalwork.3': "دست‌های خود را از برمه دور نگه دارید.", // nieuw, nalezen
    'c.metalwork.q': "چرا لبه این قدر تیز است؟", // nieuw, nalezen
    'c.metalwork.a': "هنوز پلیسه دارد.", // nieuw, nalezen
    'c.metalwork': "محکم کنید، هیچ وقت با دست نگیرید", // nieuw, nalezen
    'c.metalwork.b': "پیش برمهٔ پایه‌دار، هیچ وقت یک پرزهٔ خورد را در دست نگیرید. برمه می‌تواند آن را بگیرد و بسیار تیز دور بدهد. آن را در گیرهٔ میز کار محکم کنید. موی دراز را ببندید، و پیش برمه‌ای که دور می‌خورد دستکش نپوشید: می‌تواند دستکش را به داخل بکشد. عینک ایمنی بپوشید. بعد از اره کردن یا برمه کردن، فلز پلیسه دارد: یک لبهٔ تیز. پیش از اینکه پرزه را به دست بگیرید یا به کسی بدهید، پلیسه را با سوهان دور کنید. ذره‌های فلز را با برس پاک کنید، نه با دست.", // nieuw, nalezen
    'c.metalwork.p': "اول آن را محکم می‌کنم.", // nieuw, nalezen
    'c.metalwork.s': "باید در یک تکهٔ خورد فلز سوراخ برمه کنید. گیره روی یک میز دیگر است. چه می‌کنید؟", // nieuw, nalezen
    'c.metalwork.o1': "گیره را بیاورید، و تکه را محکم کنید.", // nieuw, nalezen
    'c.metalwork.o2': "آن را با دست خود محکم بگیرید.", // nieuw, nalezen
    'c.metalwork.o3': "دستکش بپوشید و آن را بگیرید.", // nieuw, nalezen
    'c.metalwork.w': "برمه می‌تواند یک پرزهٔ خورد را بگیرد و دور بدهد. آن وقت به دست شما می‌خورد. در گیره، پرزه شور نمی‌خورد.", // nieuw, nalezen
