    'c.assembly': "مراحل را به همان ترتیب انجام بدهید", // nieuw, nalezen
    'c.assembly.b': "در خط مونتاژ هر مرحله جا و ترتیب خود را دارد. رهنمود کار آن‌ها را نشان می‌دهد، اکثراً با عکس. مراحل را هر بار به همان ترتیب انجام بدهید، حتی وقتی فکر می‌کنید که راه تیزتری را می‌دانید. ترتیب دیگر می‌تواند محصولی بسازد که خوب معلوم می‌شود اما کار نمی‌کند. یک قطی تقریباً خالی است؟ به وقتش بگویید، تا خط ایستاد نشود. مرحله‌ای را می‌بینید که بهتر شده می‌تواند؟ به آمر تیم خود بگویید: آن وقت برای همه تغییر کرده می‌تواند.", // nieuw, nalezen
    'c.assembly.p': "به پرزه‌های نو ضرورت دارم.", // nieuw, nalezen
    'c.assembly.s': "شما برای مرحلهٔ سه یک راه تیزتر پیدا کرده‌اید. رهنمود کار چیز دیگری می‌گوید. چه می‌کنید؟", // nieuw, nalezen
