    's.fastening.1': "بولت را با آچار تورک محکم کنید.", // nieuw, nalezen
    's.fastening.2': "واشر را فراموش نکنید.", // nieuw, nalezen
    's.fastening.3': "کیبل‌ها را با بست پلاستیکی به هم ببندید.", // nieuw, nalezen
    'c.fastening.q': "این بولت باید چقدر محکم باشد؟", // nieuw, nalezen
    'c.fastening.a': "تا وقتی آچار تورک کلیک کند.", // nieuw, nalezen
    'c.fastening': "کلیک کافی است", // nieuw, nalezen
    'c.fastening.b': "آچار تورک وقتی کلیک می‌کند که بولت به اندازهٔ کافی محکم شده باشد. با کلیک بس کنید: بیشتر نچرخانید. خیلی محکم می‌تواند بولت یا پرزه را بشکند، و خیلی سست می‌تواند باز شود. پیچکش برقی هم همین طور کار می‌کند: خودش ایستاد می‌شود. هر واشر را سر جایش بگذارید: واشری که نیست، بعداً به سختی دیده می‌شود. بولت‌های خود را بشمارید. یکی اضافه مانده، یا به یکی دیگر ضرورت دارید؟ پس چیزی غلط است: به آمر تیم خود بگویید.", // nieuw, nalezen
    'c.fastening.p': "یک بولت اضافه مانده.", // nieuw, nalezen
    'c.fastening.s': "آچار تورک شما کلیک کرد. به نظر شما بولت هنوز کمی سست است. چه می‌کنید؟", // nieuw, nalezen
    'c.fastening.o1': "بس کنید، و از آمر تیم خود بپرسید.", // nieuw, nalezen
    'c.fastening.o2': "آن را با دست کمی بیشتر بچرخانید.", // nieuw, nalezen
    'c.fastening.o3': "از یک آچار درازتر استفاده کنید.", // nieuw, nalezen
    'c.fastening.w': "کلیک به زور درست تنظیم شده. اگر به نظر شما درست نیست، شاید آچار کنترول لازم دارد. بیشتر چرخاندن می‌تواند بولت را بشکند.", // nieuw, nalezen
    'l.handling': "بلند کردن و جابجا کردن", // nieuw, nalezen
    'w.takel': "کرین زنجیری (پرزه‌های سنگین را با زنجیر بلند می‌کند)", // nieuw, nalezen
