    'w.draaitafel': "میز چرخان (پرزه را می‌چرخانید، نه خود را)", // nieuw, nalezen
    'w.rolcontainer': "قفس چرخ‌دار (یک قفس بلند بالای چرخ‌ها)", // nieuw, nalezen
    's.handling.1': "این را تنها بلند نکنید. از کرین زنجیری استفاده کنید.", // nieuw, nalezen
    's.handling.2': "قلاب کرین خوب بسته است؟", // nieuw, nalezen
    's.handling.3': "کراچی پرزه‌ها را تیله کنید، آن را کش نکنید.", // nieuw, nalezen
    'c.handling.q': "اجازه دارم زیر کرین ایستاد شوم؟", // nieuw, nalezen
    'c.handling.a': "نی، هیچ وقت زیر بار آویزان.", // nieuw, nalezen
    'c.handling': "بگذارید کرین کار سنگین را بکند", // nieuw, nalezen
    'c.handling.b': "پرزه‌های سنگین با کرین زنجیری یا بالابر کمکی بلند می‌شوند، نه با کمر شما. پیش از بلند کردن قلاب را کنترول کنید: قفلک قلاب باید بسته شود. آهسته بلند کنید، و دست‌ها و پاهای خود را از بار دور نگه دارید. هیچ وقت زیر بار آویزان ایستاد نشوید یا راه نروید. برای چرخاندن یک پرزه از میز چرخان استفاده کنید: آن وقت لازم نیست کمر خود را بپیچانید. کراچی یا قفس چرخ‌دار را تیله کنید: می‌بینید که کجا می‌روید، و کمر شما کار کمتری دارد. از کرین زنجیری فقط وقتی استفاده کنید که طریقهٔ آن را یاد گرفته‌اید. مقررات در هر کمپنی فرق می‌کند: از سرپرست خود بپرسید که مقررات جای کار شما چیست.", // nieuw, nalezen
