    'c.finalcheck.b': "کنترول آخر آخرین فرصت است که یک غلطی را پیش از مشتری پیدا کنید. هر نکتهٔ لست را کنترول کنید، حتی وقتی کار زیاد است. یک خراش یا چاک خورد به آسانی از نظر می‌افتد: در روشنی خوب نگاه کنید، و از بیشتر از یک طرف. ستیکر تأیید یا تاپه را فقط وقتی بزنید که همهٔ نکته‌ها خوب باشد. مطمئن نیستید؟ محصول را یک طرف بگذارید و بپرسید. غلطی که اینجا پیدا شود کم خرچ دارد، و غلطی که به مشتری برسد خرچ زیاد. مقررات در هر کمپنی فرق می‌کند: از سرپرست خود بپرسید که مقررات جای کار شما چیست.", // nieuw, nalezen
