    'c.pests.b': "یک مریضی یا آفت در گلخانه زود پخش می‌شود. ممکن است آن را با دست‌ها، لباس‌ها و افزار خود ببرید. پس پیش هر دروازه از روی پای‌پاک ضد عفونی تیر شوید، و وقتی به بخش دیگر گلخانه می‌روید دست‌های خود را بشویید. کار خود را در قطارهای صحتمند شروع کنید، و در قطارهای مریض خلاص کنید. روی یک نبات حشره، لکه یا پوپنک می‌بینید؟ به آن دست نزنید، اما به سرپرست خود بگویید که کجاست. بعضی حشرات در گلخانه کمک‌کننده هستند: به آن‌ها کاری نداشته باشید. مقررات در هر کمپنی فرق می‌کند: از سرپرست خود بپرسید که مقررات جای کار شما چیست.", // nieuw, nalezen
