    'c.tyres.b': "آچار بادی تیز و بسیار قوی است. از آن برای باز کردن بولت‌های تایر استفاده کنید، اما نه برای محکم بستن آن‌ها. اول بولت‌ها را با دست بچرخانید و جا بیندازید. بعد آن‌ها را چلیپایی با آچار تورک محکم کنید، به اندازهٔ زوری که برای آن موتر تعیین شده. تایری که محکم نیست می‌تواند در وقت رانندگی جدا شود. گل و فشار هر تایری را که به دست می‌گیرید کنترول کنید. مقررات در هر کمپنی فرق می‌کند: از سرپرست خود بپرسید که مقررات جای کار شما چیست.", // nieuw, nalezen
